from collections import deque

def shortest_path(edges, start, goal):
    queue = deque([(start, [start])])
    visited = {start}
    while queue:
        node, path = queue.popleft()
        if node == goal:
            return path
        for neighbor in sorted(edges.get(node, [])):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))
    return None

# The visited set prevents cycles, while sorting makes equal-length answers deterministic.

struct Reading { long timestamp; double value; };

std::vector<Reading> moving_average(const std::vector<Reading>& source, std::size_t width) {
    if (width == 0) throw std::invalid_argument("width");
    std::deque<double> window;
    std::vector<Reading> result;
    double sum = 0.0;
    for (const auto& item : source) {
        window.push_back(item.value); sum += item.value;
        if (window.size() > width) { sum -= window.front(); window.pop_front(); }
        result.push_back({item.timestamp, sum / window.size()});
    }
    return result;
}
